<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div x-data="{open:false,search:''}" class="space-y-5">
 <div class="flex flex-wrap justify-between gap-3"><div><h1 class="text-3xl font-bold">Proxies de servidores</h1><p class="text-slate-400">Administra proxies de salida para el servidor principal y los balanceadores.</p></div><button @click="open=!open" class="bg-blue-700 px-5 py-2 rounded self-start">Agregar proxy</button></div>
 <form x-show="open" x-cloak method="post" action="/servers/proxies" class="bg-slate-900 border border-blue-800 rounded-xl p-5 grid md:grid-cols-4 gap-4"><?=$csrf->field()?><label>Nombre<input required name="name" maxlength="150" placeholder="Proxy Europa" class="mt-1 w-full bg-slate-800 p-2 rounded"></label><label>Servidor<select name="server_id" class="mt-1 w-full bg-slate-800 p-2 rounded"><option value="">Servidor principal</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=$e($s['name'])?> · <?=$e($s['status'])?></option><?php endforeach?></select></label><label>Tipo<select name="scheme" class="mt-1 w-full bg-slate-800 p-2 rounded"><option value="http">HTTP</option><option value="https">HTTPS</option><option value="socks5">SOCKS5</option></select></label><label>Host o IP<input required name="host" placeholder="proxy.example.com" class="mt-1 w-full bg-slate-800 p-2 rounded"></label><label>Puerto<input required type="number" min="1" max="65535" name="port" value="8080" class="mt-1 w-full bg-slate-800 p-2 rounded"></label><label>Usuario opcional<input name="username" autocomplete="off" class="mt-1 w-full bg-slate-800 p-2 rounded"></label><label>Contraseña opcional<input type="password" name="password" autocomplete="new-password" class="mt-1 w-full bg-slate-800 p-2 rounded"></label><label class="flex items-center gap-2 self-end p-2"><input type="checkbox" name="active" value="1" checked> Activar inmediatamente</label><button class="md:col-span-4 bg-emerald-700 p-2 rounded">Guardar proxy cifrado</button></form>
 <section class="grid md:grid-cols-3 gap-3"><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500 uppercase">Total</span><strong class="block text-2xl"><?=number_format(count($proxies))?></strong></div><div class="bg-slate-900 border border-emerald-900 rounded-xl p-4"><span class="text-xs text-slate-500 uppercase">Activos</span><strong class="block text-2xl text-emerald-400"><?=number_format(count(array_filter($proxies,fn($p)=>(bool)$p['active'])))?></strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><input x-model="search" @input="document.querySelectorAll('table tbody tr').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(search.toLowerCase()))" placeholder="Buscar proxy..." class="w-full bg-slate-800 p-2 rounded"></div></section>
 <div class="overflow-x-auto bg-slate-900 border border-slate-800 rounded-xl"><table class="w-full min-w-[850px] text-sm"><thead><tr class="text-left text-xs uppercase text-slate-400"><th class="p-3">Nombre</th><th>Servidor</th><th>Tipo</th><th>Host</th><th>Puerto</th><th>Usuario</th><th>Estado</th><th class="text-right p-3">Acciones</th></tr></thead><tbody><?php foreach($proxies as $p):?><tr class="border-t border-slate-800"><td class="p-3 font-semibold"><?=$e($p['name'])?></td><td><?=$e($p['server_name']??'Principal')?></td><td><?=strtoupper($e($p['scheme']))?></td><td><?=$e($p['host'])?></td><td><?=$p['port']?></td><td><?=$e($p['username']??'Sin autenticación')?></td><td><span class="px-2 py-1 rounded <?=$p['active']?'bg-emerald-700':'bg-slate-700'?>"><?=$p['active']?'Activo':'Inactivo'?></span></td><td class="p-3"><div class="flex justify-end gap-2"><form method="post" action="/servers/proxies/status"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="active" value="<?=$p['active']?'0':'1'?>"><button class="bg-amber-700 px-3 py-1 rounded"><?=$p['active']?'Desactivar':'Activar'?></button></form><form method="post" action="/servers/proxies/delete" onsubmit="return confirm('¿Eliminar este proxy?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="bg-red-800 px-3 py-1 rounded">Eliminar</button></form></div></td></tr><?php endforeach?><?php if(!$proxies):?><tr><td colspan="8" class="p-8 text-center text-slate-500">Todavía no hay proxies configurados.</td></tr><?php endif?></tbody></table></div>
</div>
